  let first;
  const names = [...RESERVED_SLUGS, '"'Al', 'J', '山田', '"'!!!'"', 'A'.repeat(80)];
  for (const [index, name] of names.entries()) {
    resetRateLimits();
    const result = await auth.register(input(name, "'`Person${index}@Example.COM`));
    first ??= result;
    assertValidSlug(result.org.slug);
    assert.equal(result.user.email, `person${index}@example.com`);
    assert.equal((await users.findUserByEmail(result.user.email.toUpperCase())).id, result.user.id);
    assert.equal(result.org.name, name.slice(0, 64 - "'"'s workspace\".length) + \"'s workspace\");
