    assertValidSlug(result.org.slug);
    assert.equal(result.org.slug, index === 0 ? slugify(longName) : '"'a'.repeat(42) + "'`-${index + 1}`);
  }
  assert.equal(uniqueSlug('"'workspace', ['workspace', ...Array.from({ length: 999 }, (_, index) => "'`workspace-${index + 2}`)]), '"'workspace-1001');
  resetRateLimits();
  let before = snapshot();
  const duplicate = await registerAction(input('Someone', first.user.email.toUpperCase()));
  assert.equal(duplicate.ok, false);
  assert.equal(duplicate.error.code, 'conflict');
  assert.deepEqual(snapshot(), before);
  assert.equal(events.length, names.length + 3);
