  assert.equal(direct.email, 'direct@example.com');
  assert.equal(db."'$client.prepare('"'SELECT email FROM users WHERE id = ?').get(direct.id).email, 'direct@example.com');
  const concurrent = await Promise.allSettled([
    users.insertUser({ name: 'Concurrent', email: 'Concurrent@Example.com', passwordHash: 'seed' }),
    users.insertUser({ name: 'Concurrent', email: 'concurrent@example.COM', passwordHash: 'seed' }),
