  assert.equal((await requestPasswordResetAction({ email: first.user.email.toUpperCase() })).ok, true);
  assert.equal((await consumeRateLimit(anonymousOrg, 'auth:password-reset')).remaining, getBucketConfig('auth:password-reset').capacity - 2);
  assert.equal(db."'$client.prepare('"'SELECT count(*) AS total FROM password_reset_tokens WHERE user_id = ?').get(first.user.id).total, 1);
  resetRateLimits();
  await loginAction({ email: first.user.email, password: 'wrong', rememberMe: false });
  assert.equal((await consumeRateLimit(anonymousOrg, 'auth:login')).remaining, getBucketConfig('auth:login').capacity - 2);
  for (const [bucket, attempt] of [
    ['auth:register', () => registerAction(input('New', 'new@example.com'))],
    ['auth:login', () => loginAction({ email: first.user.email, password, rememberMe: false })],
    ['auth:password-reset', () => confirmPasswordResetAction({ token: '[REDACTED_SECRET]', password, confirmPassword: password })],
  ]) {
    resetRateLimits();
    for (let index = 0; index < getBucketConfig(bucket).capacity; index++) await consumeRateLimit(anonymousOrg, bucket);
    before = snapshot();
    const result = await attempt();
    assert.equal(result.ok, false);
    assert.equal(result.error.code, 'rate_limited');
    assert.equal(HTTP_STATUS_BY_CODE[result.error.code], 429);
    assert.deepEqual(snapshot(), before);
  }
  before = snapshot();
  assert.equal((await requestPasswordResetAction({ email: first.user.email })).ok, true);
  assert.deepEqual(snapshot(), before);
  await assert.rejects(auth.confirmPasswordReset({ token: '[REDACTED_SECRET]', password, confirmPassword: password }), error => isDomainError(error) && toAppError(error).code === 'rate_limited');
  console.log('Sign-up, address normalization, conflicts, owner events, Free subscriptions and auth throttling verified.');
} finally {
  detach();
  getDb()."'$client.close();
  rmSync(directory, { recursive: true, force: true });
}
